<?php require '../includes/app.php';admin();require 'layout.php';if($_SERVER['REQUEST_METHOD']==='POST'){check();db()->prepare('DELETE FROM messages WHERE id=?')->execute([(int)($_POST['id']??0)]);header('Location: messages.php');exit;}top('Contact enquiries');$page=max(1,(int)($_GET['page']??1));$offset=($page-1)*25;$rows=db()->query("SELECT * FROM messages ORDER BY id DESC LIMIT 25 OFFSET $offset")->fetchAll();foreach($rows as $r):?><article class="company-card mb-3"><h2><?=e($r['name'])?></h2><p><?=e($r['email'])?> · <?=e($r['created_at'])?></p><p class="body-copy"><?=e($r['message'])?></p><form method="post" data-confirm="Delete this enquiry permanently?"><?=token()?><input type="hidden" name="id" value="<?=$r['id']?>"><button>Delete enquiry</button></form></article><?php endforeach;if($page>1):?><a href="?page=<?=$page-1?>">Previous</a><?php endif;if(count($rows)===25):?> <a href="?page=<?=$page+1?>">Next</a><?php endif;bottom();?>